function buildContactMilestoneShareRecord(status, existingMilestones, specificBadge) {
	const badge = specificBadge && specificBadge.earned ? specificBadge : [...status.badges].reverse().find((b) => b.earned);
	if (badge) {
		const existing = existingMilestones.find((m) => m.contactKey === status.contactKey && m.days === badge.days);
		const matchingRun = status.milestoneRuns?.find((r) => r.days === badge.days);
		const reachedDate = existing?.reachedDate ?? matchingRun?.reachedDate ?? badge.unlockedEatDate ?? status.lastConnectedDate ?? "";
		const streakStartDate = existing?.streakStartDate ?? matchingRun?.streakStartDate ?? status.currentStreakStartDate ?? reachedDate;
		return existing ?? {
			id: `${status.contactKey}:${badge.days}:${streakStartDate}`,
			contactKey: status.contactKey,
			days: badge.days,
			streakStartDate,
			reachedDate,
			badgeId: badge.id,
			badgeTitle: badge.title,
			points: badge.points,
			awardedAt: Date.now(),
			celebratedAt: Date.now()
		};
	}
	const days = status.currentStreak > 0 ? status.currentStreak : status.longestStreak;
	if (days <= 0) return null;
	const reachedDate = status.lastConnectedDate ?? "";
	const streakStartDate = status.currentStreakStartDate ?? reachedDate;
	return {
		id: `${status.contactKey}:streak:${days}:${streakStartDate}`,
		contactKey: status.contactKey,
		days,
		streakStartDate,
		reachedDate,
		badgeId: `streak-${days}`,
		badgeTitle: days === 1 ? "1-Day Streak" : `${days}-Day Streak`,
		points: status.contactScore,
		awardedAt: Date.now(),
		celebratedAt: Date.now()
	};
}
function looksLikePhoneNumber(value) {
	const clean = (value ?? "").trim();
	if (!clean) return false;
	const compact = clean.replace(/[\s().-]/g, "");
	if (/^\+?\d{6,}$/.test(compact)) return true;
	const digitsOnly = clean.replace(/\D/g, "");
	return digitsOnly.length >= 7 && digitsOnly.length >= clean.replace(/\s+/g, "").length * .7;
}
